files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8d99ae;
  --border: #0f3460;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image:
    linear-gradient(45deg, rgba(255,255,255,0.03) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(255,255,255,0.03) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, rgba(255,255,255,0.03) 75%),
    linear-gradient(-45deg, transparent 75%, rgba(255,255,255,0.03) 75%);
  background-size: 16px 16px;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0;
  font-family: 'Courier New', monospace;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  width: 100%;
  max-width: 480px;
  background: var(--card);
  border: 4px solid var(--border);
  padding: 24px;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
}

h1 {
  margin: 0 0 20px;
  font-size: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--border);
}

.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

#todo-input {
  flex: 1;
  min-width: 0;
  padding: 10px 12px;
  font-family: inherit;
  font-size: 16px;
  color: var(--text);
  background: var(--bg);
  border: 3px solid var(--border);
  outline: none;
}

#todo-input:focus-visible {
  border-color: var(--accent);
}

button {
  font-family: inherit;
  font-size: 16px;
  cursor: pointer;
  border: 3px solid var(--border);
  background: var(--accent);
  color: #fff;
  padding: 10px 16px;
  transition: transform 0.05s, background 0.1s;
}

button:hover { background: #ff5c77; }
button:active { transform: translate(2px, 2px); }
button:focus-visible { outline: 3px solid var(--text); outline-offset: 2px; }

.counters {
  display: flex;
  gap: 20px;
  margin-bottom: 16px;
  font-size: 16px;
  color: var(--muted);
}

.counters strong { color: var(--text); }

.todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px;
  background: var(--bg);
  border: 3px solid var(--border);
}

.todo-item input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--accent);
  cursor: pointer;
}

.todo-item span {
  flex: 1;
  word-break: break-word;
  font-size: 16px;
}

.todo-item.done span {
  text-decoration: line-through;
  color: var(--muted);
}

.todo-item .delete {
  background: transparent;
  color: var(--accent);
  padding: 4px 10px;
  border-color: var(--accent);
}

.todo-item .delete:hover { background: var(--accent); color: #fff; }

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

(function () {
  'use strict';

  var tasks = [];
  var nextId = 1;

  var input = document.getElementById('todo-input');
  var addBtn = document.getElementById('todo-add');
  var list = document.getElementById('todo-list');
  var totalEl = document.getElementById('todo-total');
  var remainingEl = document.getElementById('remaining');

  function updateCounts() {
    totalEl.textContent = String(tasks.length);
    var remaining = tasks.filter(function (t) { return !t.done; }).length;
    remainingEl.textContent = String(remaining);
  }

  function createItem(task) {
    var li = document.createElement('li');
    li.className = 'todo-item' + (task.done ? ' done' : '');

    var checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = 'todo-check-' + task.id;
    checkbox.checked = task.done;
    checkbox.setAttribute('aria-label', 'Mark task complete: ' + task.text);
    checkbox.addEventListener('change', function () {
      task.done = checkbox.checked;
      li.classList.toggle('done', task.done);
      updateCounts();
    });

    var span = document.createElement('span');
    span.id = 'todo-text-' + task.id;
    span.textContent = task.text;

    var del = document.createElement('button');
    del.type = 'button';
    del.className = 'delete';
    del.id = 'todo-delete-' + task.id;
    del.textContent = '\u2715';
    del.setAttribute('aria-label', 'Delete task: ' + task.text);
    del.addEventListener('click', function () {
      tasks = tasks.filter(function (t) { return t.id !== task.id; });
      li.remove();
      updateCounts();
    });

    li.appendChild(checkbox);
    li.appendChild(span);
    li.appendChild(del);
    return li;
  }

  function addTask() {
    var text = input.value.trim();
    if (!text) { return; }
    var task = { id: nextId++, text: text, done: false };
    tasks.push(task);
    list.appendChild(createItem(task));
    input.value = '';
    input.focus();
    updateCounts();
  }

  addBtn.addEventListener('click', addTask);
  input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') { addTask(); }
  });

  updateCounts();
})();
